(284327, 19952, 509, '<td valign="top">Lol, nice, but I don''t think the text is "politically correct" enough for an advertisement</td>', 'Lol, nice, but I don''t think the text is "politically correct" enough for an advertisement', '2003-05-01 01:13:20.000000', NULL, 1),
(284332, 20037, 509, '<td valign="top">My favorite of the DCP Prints images.  This one demonstrates quality, which is the message I think should be sent to entice buyers.  Great job!</td>', 'My favorite of the DCP Prints images.  This one demonstrates quality, which is the message I think should be sent to entice buyers.  Great job!', '2003-05-01 01:16:13.000000', NULL, 1),
(284337, 19930, 4967, '<td valign="top">Oops... I think this was meant for the other sticker challenge...</td>', 'Oops... I think this was meant for the other sticker challenge...', '2003-05-01 01:19:51.000000', NULL, 1),
(284339, 20064, 2, '<td valign="top">This is my favorite of the prints stickers.  Not too much going on.  Emphasis on the prints.  Very clean design.  Nice job.</td>', 'This is my favorite of the prints stickers.  Not too much going on.  Emphasis on the prints.  Very clean design.  Nice job.', '2003-05-01 01:22:24.000000', NULL, 1),
(284341, 20037, 4967, '<td valign="top">I love this one... it has my vote for favorite!  -10-  Good luck!</td>', 'I love this one... it has my vote for favorite!  -10-  Good luck!', '2003-05-01 01:23:25.000000', NULL, 1),
(284355, 19825, 2, '<td valign="top">This is a very nice design.  If printed, you would probably need to adjust your images so they weren''t falling off the sticker.  Otherwise a pretty effective design.</td>', 'This is a very nice design.  If printed, you would probably need to adjust your images so they weren''t falling off the sticker.  Otherwise a pretty effective design.', '2003-05-01 01:31:22.000000', NULL, 1),
(284356, 20037, 2, '<td valign="top">I love how this one pops out at you.  I wish the url were a little more readable, and I''m not 100% convinced of the connection from the statue to prints, BUT I gave you a 9 :)</td>', 'I love how this one pops out at you.  I wish the url were a little more readable, and I''m not 100% convinced of the connection from the statue to prints, BUT I gave you a 9 :)', '2003-05-01 01:32:35.000000', NULL, 1),
(284359, 19945, 2104, '<td valign="top">The claim of "the largest collection of printed photo artwork online" - iffy. There are sites such as art.com that have very large collections of proffesional photographers'' works. Also, daprints.com has a large selection of photographic prints. Don''t make claims unless they can be backed up ;)</td>', 'The claim of "the largest collection of printed photo artwork online" - iffy. There are sites such as art.com that have very large collections of proffesional photographers'' works. Also, daprints.com has a large selection of photographic prints. Don''t make claims unless they can be backed up ;)', '2003-05-01 01:33:32.000000', NULL, 1),
(284360, 19626, 1, '<td valign="top">love the dotted camera and use indication of color.</td>', 'love the dotted camera and use indication of color.', '2003-05-01 01:33:49.000000', NULL, 1),
(284362, 19811, 1, '<td valign="top">Great slogan, though not done as best as it could''ve been done.</td>', 'Great slogan, though not done as best as it could''ve been done.', '2003-05-01 01:34:41.000000', NULL, 1),
(284412, 19795, 4494, '<td valign="top">So far I think this is the best.  9.  I looked at all of these (for the first time) from a thumbnail view first and this one really stands out.  Good job!</td>', 'So far I think this is the best.  9.  I looked at all of these (for the first time) from a thumbnail view first and this one really stands out.  Good job!', '2003-05-01 02:02:51.000000', NULL, 1),
