(287698, 20037, 5728, '<td valign="top">This sticker is very good, has lots of charachter and, yes, I would put it on the back of my car :-)</td>', 'This sticker is very good, has lots of charachter and, yes, I would put it on the back of my car :-)', '2003-05-05 08:15:10.000000', NULL, 1),
(288219, 19945, 3102, '<td valign="top">The design is very appealing, although I think the tagline would technically be a lie since there are many sites with a larger quantity of works.</td>', 'The design is very appealing, although I think the tagline would technically be a lie since there are many sites with a larger quantity of works.', '2003-05-05 16:49:53.000000', NULL, 1),
(288372, 19811, 6202, '<td valign="top">Very cute saying but I think it would have been much better represented by having some kind of background other than white, prehaps a muted out photo to represent a print would have helped.</td>', 'Very cute saying but I think it would have been much better represented by having some kind of background other than white, prehaps a muted out photo to represent a print would have helped.', '2003-05-05 19:48:17.000000', NULL, 1),
(288376, 19418, 6202, '<td valign="top">the colors catch your attention but that is about it, doesn''t really say much about dpcprints</td>', 'the colors catch your attention but that is about it, doesn''t really say much about dpcprints', '2003-05-05 19:49:12.000000', NULL, 1),
(288377, 20102, 6202, '<td valign="top">I feel it needs a photo included in the sticker to represent a print.</td>', 'I feel it needs a photo included in the sticker to represent a print.', '2003-05-05 19:50:04.000000', NULL, 1),
