(288383, 19795, 6202, '<td valign="top">This was one of the few that didn''t have photos included in the design that I actually like.  The ribbon looks nice with the color wheel done on it.</td>', 'This was one of the few that didn''t have photos included in the design that I actually like.  The ribbon looks nice with the color wheel done on it.', '2003-05-05 19:52:11.000000', NULL, 1),
(288387, 20137, 6202, '<td valign="top">This would have been better represented with some image being used as a backround.</td>', 'This would have been better represented with some image being used as a backround.', '2003-05-05 19:53:44.000000', NULL, 1),
(288389, 19580, 6202, '<td valign="top">the  photo you used is nice and very pretty but your letters seem to be in need of a little TLC to make them work better.</td>', 'the  photo you used is nice and very pretty but your letters seem to be in need of a little TLC to make them work better.', '2003-05-05 19:55:37.000000', NULL, 1),
(288661, 19799, 6325, '<td valign="top">Clean design.</td>', 'Clean design.', '2003-05-06 01:45:40.000000', NULL, 1),
