(288671, 20155, 6325, '<td valign="top">Much too busy for a sticker.</td>', 'Much too busy for a sticker.', '2003-05-06 01:52:09.000000', NULL, 1),
(288672, 20140, 6325, '<td valign="top">Much too much information for a sticker.</td>', 'Much too much information for a sticker.', '2003-05-06 01:53:46.000000', NULL, 1),
(288929, 19825, 7723, '<td valign="top">Simple design. Straight to the point. B/W &amp; color prints shown in framed state explain indirectly what the PRINTS word in yellow means. The url shows where to go for the prints. The white area could have been textured to add richness to the sticker as a whole. So a minus point there.</td>', 'Simple design. Straight to the point. B/W & color prints shown in framed state explain indirectly what the PRINTS word in yellow means. The url shows where to go for the prints. The white area could have been textured to add richness to the sticker as a whole. So a minus point there.', '2003-05-06 10:32:00.000000', NULL, 1),
(288932, 19795, 3791, '<td valign="top">same comments as the dpchallenge.com sticker entry...</td>', 'same comments as the dpchallenge.com sticker entry...', '2003-05-06 10:38:32.000000', NULL, 1),
(288936, 19799, 3791, '<td valign="top">very nice, did you try plain white text at the bottom?</td>', 'very nice, did you try plain white text at the bottom?', '2003-05-06 10:42:07.000000', NULL, 1),
